"use client";

import { useState, useEffect } from "react";
import Dashboard from "@/app/components/Dashboard";
import ChatAssistant from "@/app/components/ChatAssistant";
import { getAllPapers, type PaperData } from "@/app/lib/data-fetcher";

export default function Home() {
  const [papers, setPapers] = useState<PaperData[]>([]);
  const [selectedPaperIndex, setSelectedPaperIndex] = useState<number | null>(null);

  useEffect(() => {
    // We can still call this "server-side" logic since it's a small app, 
    // but for now let's just use it to populate state.
    // In a real app we'd fetch from an API route.
    const data = getAllPapers();
    setPapers(data);
  }, []);

  return (
    <main className="flex h-screen overflow-hidden bg-[#0a0f1d]">
      {/* Left Pane: Chat Interaction */}
      <div className="w-[400px] xl:w-[450px] border-r border-slate-800/50 flex-shrink-0 bg-[#0f172a]/40 backdrop-blur-3xl">
        <ChatAssistant
          selectedPaper={selectedPaperIndex !== null ? papers[selectedPaperIndex] : null}
          onSelectPaper={(idx) => setSelectedPaperIndex(idx)}
        />
      </div>

      {/* Right Pane: Intelligence / Visualization */}
      <div className="flex-1 overflow-y-auto custom-scrollbar relative">
        <Dashboard
          papers={papers}
          selectedPaperIndex={selectedPaperIndex}
          onSelectPaper={(idx) => setSelectedPaperIndex(idx)}
        />
      </div>
    </main>
  );
}
