import fs from "fs";
import path from "path";

// Let's re-use the types from the previous data.ts and export them from here.
export interface TargetMaterial {
    target_material: {
        chemical_formula: string;
        material_name: string;
        material_class: string;
    };
    evidence: string;
}

export interface SubstrateInfo {
    substrate_material: string;
    substrate_orientation: string;
    pretreatment: string;
    surface_functionalization: string;
    evidence: string;
}

export interface DepositionConditions {
    deposition_temperature_C: number | null;
    pressure: string | null;
    precursor_pulse_time_s: number | null;
    coreactant_pulse_time_s: number | null;
    purge_time_s: number | null;
    number_of_cycles: number | null;
    reactor_type: string | null;
    evidence: string;
}

export interface Chemical {
    abbreviation: string;
    full_name: string;
}

export interface PrecursorCoreactant {
    precursors: Chemical[];
    coreactants: Chemical[];
    purge_gas: Chemical[];
    carrier_gas: Chemical[];
    evidence: string;
}

export interface ReactionConditions {
    reaction_equations: string[];
    surface_mechanism_description: string;
    intermediate_species: string[];
    evidence: string;
}

export interface FilmProperties {
    film_thickness_nm: number | null;
    density_g_cm3: number | null;
    refractive_index: number | null;
    surface_roughness_nm: number | null;
    crystal_phase: string | null;
    evidence: string;
}

export interface Characterization {
    characterization_methods: string[];
    evidence: string;
}

export interface Summary {
    target_material: string;
    process_type: string;
    main_precursors: string[];
    temperature_range: string;
    summary: string;
    evidence: string;
}

export interface PaperData {
    id: string;
    label: string;
    summary: Summary;
    target_material: TargetMaterial;
    substrate_info: SubstrateInfo;
    deposition_conditions: DepositionConditions;
    precursor_coreactant: PrecursorCoreactant;
    reaction_conditions: ReactionConditions;
    film_properties: FilmProperties;
    characterization: Characterization;
}

function safeJsonParse<T>(filePath: string, defaultFallback: unknown): T {
    try {
        const data = fs.readFileSync(filePath, "utf-8");
        return JSON.parse(data) as T;
    } catch (err) {
        console.warn(`Could not read or parse ${filePath}`);
        return defaultFallback as T;
    }
}

export function getAllPapers(): PaperData[] {
    const extractedDataDir = path.join(process.cwd(), "..", "extracted_data");

    if (!fs.existsSync(extractedDataDir)) {
        console.error("extracted_data directory not found at " + extractedDataDir);
        return [];
    }

    const dirs = fs.readdirSync(extractedDataDir, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory() && dirent.name.startsWith("paper"))
        .map(dirent => dirent.name);

    // Sorting alphanumerically, so paper2 comes before paper10
    dirs.sort((a, b) => {
        const numA = parseInt(a.replace("paper", ""), 10) || 0;
        const numB = parseInt(b.replace("paper", ""), 10) || 0;
        return numA - numB;
    });

    const papers: PaperData[] = [];

    for (const dirName of dirs) {
        const paperDir = path.join(extractedDataDir, dirName);

        // Read the required JSON files with safe fallbacks
        const summary = safeJsonParse<Summary>(path.join(paperDir, "summary.json"), {
            target_material: "N/A", process_type: "N/A", main_precursors: [], temperature_range: "N/A", summary: "", evidence: ""
        });

        const target_material = safeJsonParse<TargetMaterial>(path.join(paperDir, "target_material.json"), {
            target_material: { chemical_formula: "", material_name: "", material_class: "" }, evidence: ""
        });

        const substrate_info = safeJsonParse<SubstrateInfo>(path.join(paperDir, "substrate_info.json"), {
            substrate_material: "", substrate_orientation: "", pretreatment: "", surface_functionalization: "", evidence: ""
        });

        const deposition_conditions = safeJsonParse<DepositionConditions>(path.join(paperDir, "deposition_conditions.json"), {
            deposition_temperature_C: null, pressure: null, precursor_pulse_time_s: null, coreactant_pulse_time_s: null, purge_time_s: null, number_of_cycles: null, reactor_type: null, evidence: ""
        });

        const precursor_coreactant = safeJsonParse<PrecursorCoreactant>(path.join(paperDir, "precursor_coreactant.json"), {
            precursors: [], coreactants: [], purge_gas: [], carrier_gas: [], evidence: ""
        });

        const reaction_conditions = safeJsonParse<ReactionConditions>(path.join(paperDir, "reaction_conditions.json"), {
            reaction_equations: [], surface_mechanism_description: "", intermediate_species: [], evidence: ""
        });

        const film_properties = safeJsonParse<FilmProperties>(path.join(paperDir, "film_properties.json"), {
            film_thickness_nm: null, density_g_cm3: null, refractive_index: null, surface_roughness_nm: null, crystal_phase: null, evidence: ""
        });

        const characterization = safeJsonParse<Characterization>(path.join(paperDir, "characterization.json"), {
            characterization_methods: [], evidence: ""
        });

        papers.push({
            id: dirName,
            label: `${dirName.toUpperCase()} — ${target_material.target_material.chemical_formula || "Unknown"} via ${summary.process_type || "CVD/ALD"}`,
            summary,
            target_material,
            substrate_info,
            deposition_conditions,
            precursor_coreactant,
            reaction_conditions,
            film_properties,
            characterization
        });
    }

    return papers;
}
